/**
 Do not return anything, modify matrix in-place instead.
 */
function setZeroes(matrix: number[][]): void {
  const m = matrix.length;
  const n = matrix[0].length;

  // Первая строка и первый столбец станут флагами для остальных строк/столбцов.
  // Но их собственные нули нужно запомнить отдельно, иначе флаги их затрут
  const firstRowZero = matrix[0].some((v) => v === 0);
  let firstColZero = false;
  for (let r = 0; r < m; r++) {
    if (matrix[r][0] === 0) firstColZero = true;
  }

  // 1. Помечаем: ноль в (r, c) → обнулить строку r и столбец c
  for (let r = 1; r < m; r++) {
    for (let c = 1; c < n; c++) {
      if (matrix[r][c] === 0) {
        matrix[r][0] = 0; // флаг строки
        matrix[0][c] = 0; // флаг столбца
      }
    }
  }

  // 2. Обнуляем внутреннюю часть по флагам (флаги пока не трогаем)
  for (let r = 1; r < m; r++) {
    for (let c = 1; c < n; c++) {
      if (matrix[r][0] === 0 || matrix[0][c] === 0) {
        matrix[r][c] = 0;
      }
    }
  }

  // 3. В самом конце обрабатываем первую строку и первый столбец
  if (firstRowZero) {
    for (let c = 0; c < n; c++) matrix[0][c] = 0;
  }
  if (firstColZero) {
    for (let r = 0; r < m; r++) matrix[r][0] = 0;
  }
}

// Время: O(m · n) — несколько проходов по матрице
// Память: O(1) — флаги хранятся в самой матрице
